"use server";
import { majorToMinor } from "@/lib/dispatch/booking-validation";
import { submitSecureVendorOfferResponse,submitVendorFulfillmentProposal } from "@/lib/dispatch/vendor-offer-portal-repository";
import { VENDOR_DECLINE_REASONS } from "@/lib/dispatch/vendor-offer-portal-types";
const value=(form:FormData,key:string)=>String(form.get(key)??"").trim();
export async function respondToVendorOffer(token:string,form:FormData):Promise<{ok:boolean;message:string}>{try{const kind=value(form,"kind");if(kind==="accepted")await submitSecureVendorOfferResponse(token,{kind});else if(kind==="declined"){const declineReason=value(form,"declineReason"),note=value(form,"note");if(!VENDOR_DECLINE_REASONS.includes(declineReason as never))throw new Error("Select a decline reason.");if(declineReason==="other"&&note.length<3)throw new Error("Add a short reason.");await submitSecureVendorOfferResponse(token,{kind,declineReason:declineReason as never,...(note?{note}:{})})}else if(kind==="countered"){const requestedPayoutMinor=majorToMinor(value(form,"requestedPayout"),"Requested payout"),note=value(form,"note");await submitSecureVendorOfferResponse(token,{kind,requestedPayoutMinor,...(note?{note}:{})})}else throw new Error("Select a valid response.");return{ok:true,message:kind==="accepted"?"Accepted — now propose an eligible Driver and Vehicle for RentKA review.":kind==="declined"?"Declined. RentKA will review your response.":"Counter submitted — awaiting RentKA review."}}catch(error){return{ok:false,message:error instanceof Error?error.message:"Unable to submit vendor response."}}}
export async function proposeVendorResources(token:string,form:FormData):Promise<{ok:boolean;message:string}>{try{const driverId=value(form,"driverId"),vehicleId=value(form,"vehicleId");if(!driverId||!vehicleId)throw new Error("Select an eligible Driver and Vehicle.");const result=await submitVendorFulfillmentProposal(token,{driverId,vehicleId});return{ok:true,message:result.duplicate?"This fulfillment proposal is already current.":"Fulfillment proposal saved for RentKA review. The booking is not assigned."}}catch(error){return{ok:false,message:error instanceof Error?error.message:"Unable to save fulfillment proposal."}}}
